<template>
<div class="page">
<v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center flex-wrap"><div><div class="text-overline">SALES</div><h1 class="text-h5 font-weight-bold">Bookings</h1><div class="grey--text">Manage reservations, confirmations and completed sales.</div></div><v-spacer/><v-btn v-if="$can('sales.create')" color="#165134" dark depressed class="rounded-lg" @click="openCreate"><v-icon left>mdi-bookmark-plus</v-icon>New Booking</v-btn></div></v-card>
<v-row class="mb-1">
  <v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Bookings Shown</div><div class="text-h6 font-weight-bold">{{items.length}}</div></v-card></v-col>
  <v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Reserved</div><div class="text-h6 font-weight-bold orange--text">{{reservedCount}}</div></v-card></v-col>
  <v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Confirmed</div><div class="text-h6 font-weight-bold blue--text">{{confirmedCount}}</div></v-card></v-col>
  <v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Outstanding Shown</div><div class="text-h6 font-weight-bold error--text">PKR {{money(outstandingShown)}}</div></v-card></v-col>
</v-row>
<v-card flat class="filter-card pa-3 mb-4"><v-row dense align="center"><v-col cols="12" md="6"><v-text-field v-model="search" outlined dense clearable prepend-inner-icon="mdi-magnify" label="Search booking or customer" @keyup.enter="load" @click:clear="load"/></v-col><v-col cols="12" md="3"><v-select v-model="status" :items="statuses" outlined dense clearable label="Status" @change="load"/></v-col><v-col cols="12" md="3" class="text-right"><v-chip>{{items.length}} shown</v-chip></v-col></v-row></v-card>
<v-card flat class="table-card"><v-data-table :headers="headers" :items="items" mobile-breakpoint="700"><template v-slot:item.customer.name="{item}"><div class="py-2"><div class="font-weight-medium">{{item.customer ? item.customer.name : '—'}}</div><div class="caption grey--text">{{item.customer ? item.customer.phone : ''}}</div></div></template><template v-slot:item.property.property_number="{item}"><div><div class="font-weight-medium">{{item.property ? item.property.property_number : '—'}}</div><div class="caption grey--text">{{item.property && item.property.project ? item.property.project.name : ''}}</div></div></template><template v-slot:item.status="{item}"><v-chip x-small dark :color="color(item.status)">{{item.status}}</v-chip></template><template v-slot:item.final_price="{item}">{{money(item.final_price)}}</template><template v-slot:item.remaining_amount="{item}"><span :class="{'error--text':Number(item.remaining_amount)>0}">{{money(item.remaining_amount)}}</span></template><template v-slot:item.actions="{item}">
<v-btn v-if="$can('sales.view')" icon small title="Documents" @click="openDocuments(item)"><v-icon small>mdi-file-document-multiple-outline</v-icon></v-btn>
<v-btn v-if="$can('installments.create') && ['reserved','confirmed'].includes(item.status) && Number(item.remaining_amount)>0" icon small color="purple" title="Create installment plan" @click="createInstallmentPlan(item)"><v-icon small>mdi-calendar-plus</v-icon></v-btn>
<v-btn v-if="$can('payments.create') && ['reserved','confirmed'].includes(item.status) && Number(item.remaining_amount)>0" icon small color="#165134" title="Record payment" @click="recordPayment(item)"><v-icon small>mdi-cash-plus</v-icon></v-btn>
<v-btn v-if="$can('commissions.create') && item.sales_agent_id && item.status!=='cancelled'" icon small color="teal" title="Create commission" @click="createCommission(item)"><v-icon small>mdi-percent-outline</v-icon></v-btn>
<v-btn v-if="$can('sales.edit') && item.status==='reserved'" icon small color="blue" title="Confirm booking" @click="transition(item,'confirm')"><v-icon small>mdi-check</v-icon></v-btn>
<v-btn v-if="$can('sales.edit') && ['reserved','confirmed'].includes(item.status)" icon small color="error" title="Cancel booking" @click="transition(item,'cancel')"><v-icon small>mdi-close</v-icon></v-btn>
<v-btn v-if="$can('sales.edit') && item.status==='confirmed' && Number(item.remaining_amount)<=0" icon small color="success" title="Complete sale" @click="transition(item,'complete')"><v-icon small>mdi-check-circle</v-icon></v-btn>
</template></v-data-table></v-card>
<v-dialog v-model="dialog" max-width="760" persistent><v-card><v-card-title><div><div class="text-h6 font-weight-bold">New Booking</div><div class="caption grey--text">Reserve an available property for a customer.</div></div><v-spacer/><v-btn icon @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text><v-alert outlined type="info" dense>Only available properties can be reserved.</v-alert><v-row>
<v-col cols="12" md="6"><v-autocomplete v-model="form.customer_id" :items="customers" item-text="name" item-value="id" outlined dense clearable label="Customer *" prepend-inner-icon="mdi-account"/></v-col>
<v-col cols="12" md="6"><v-autocomplete v-model="form.property_id" :items="properties" item-text="property_number" item-value="id" outlined dense clearable label="Available Property *" prepend-inner-icon="mdi-home-city"><template v-slot:item="{item}"><v-list-item-content><v-list-item-title>{{item.property_number}} — {{item.project ? item.project.name : 'Property'}}</v-list-item-title><v-list-item-subtitle>{{money(item.price)}} · {{item.status}}</v-list-item-subtitle></v-list-item-content></template></v-autocomplete></v-col>
<v-col cols="12" md="6"><v-autocomplete v-model="form.sales_agent_id" :items="agents" item-text="name" item-value="id" outlined dense clearable label="Sales Agent" prepend-inner-icon="mdi-account-tie"/></v-col>
<v-col cols="12" md="6"><v-text-field v-model="form.discount" type="number" min="0" outlined dense label="Discount" prepend-inner-icon="mdi-sale"/></v-col>
<v-col cols="12"><v-textarea v-model="form.notes" outlined dense rows="2" label="Notes"/></v-col></v-row></v-card-text><v-card-actions><v-spacer/><v-btn text @click="dialog=false">Cancel</v-btn><v-btn v-if="$can('sales.create')" color="#165134" dark :disabled="!form.customer_id || !form.property_id" @click="save">Reserve Property</v-btn></v-card-actions></v-card></v-dialog>
<v-dialog v-model="documentsDialog" max-width="850"><v-card><v-card-title>Booking Documents <span v-if="selectedBooking" class="ml-2 caption grey--text">{{selectedBooking.booking_number}}</span><v-spacer/><v-btn icon @click="documentsDialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-divider/><v-card-text class="pt-5"><v-row v-if="$can('documents.create')" dense><v-col cols="12" md="4"><v-select v-model="documentForm.document_type" :items="documentTypes" label="Document Type" outlined dense/></v-col><v-col cols="12" md="5"><v-file-input v-model="documentForm.document" label="Choose file" outlined dense accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png" prepend-icon="mdi-paperclip"/></v-col><v-col cols="12" md="3"><v-btn block color="#165134" dark :disabled="!documentForm.document_type||!documentForm.document" @click="uploadDocument"><v-icon left>mdi-upload</v-icon>Upload</v-btn></v-col><v-col cols="12"><v-text-field v-model="documentForm.notes" label="Notes (optional)" outlined dense/></v-col></v-row><v-data-table :headers="documentHeaders" :items="documents" :items-per-page="10"><template v-slot:item.file_size="{item}">{{fileSize(item.file_size)}}</template><template v-slot:item.actions="{item}"><v-btn icon small title="Download" @click="downloadDocument(item)"><v-icon small>mdi-download</v-icon></v-btn><v-btn v-if="$can('documents.delete')" icon small color="error" title="Delete" @click="deleteDocument(item)"><v-icon small>mdi-delete</v-icon></v-btn></template><template v-slot:no-data><div class="pa-5 grey--text">No documents uploaded for this booking.</div></template></v-data-table></v-card-text></v-card></v-dialog>
</div></template>
<script>
import api from '../../../services/api'
export default {name:'Bookings',data(){return{loading:false,saving:false,dialog:false,documentsDialog:false,documentsLoading:false,uploading:false,selectedBooking:null,documents:[],documentTypes:['Booking Form','CNIC Copy','Agreement','Allotment Letter','Transfer Document','Payment Document','NOC','Other'],documentForm:{document_type:null,document:null,notes:''},documentHeaders:[{text:'Type',value:'document_type'},{text:'File',value:'name'},{text:'Size',value:'file_size'},{text:'Uploaded By',value:'uploader.name'},{text:'Actions',value:'actions',sortable:false}],search:'',status:null,items:[],customers:[],properties:[],agents:[],loadingCustomers:false,loadingProperties:false,loadingAgents:false,statuses:['reserved','confirmed','completed','cancelled'],headers:[{text:'Booking #',value:'booking_number'},{text:'Customer',value:'customer.name'},{text:'Property',value:'property.property_number'},{text:'Status',value:'status'},{text:'Final Price',value:'final_price'},{text:'Remaining',value:'remaining_amount'},{text:'Actions',value:'actions',sortable:false}],form:{customer_id:null,property_id:null,sales_agent_id:null,discount:0,notes:''}}},computed:{reservedCount(){return this.items.filter(function(x){return x.status==='reserved'}).length},confirmedCount(){return this.items.filter(function(x){return x.status==='confirmed'}).length},outstandingShown(){return this.items.reduce(function(n,x){return n+Number(x.remaining_amount||0)},0)}},mounted(){this.load();if(this.$route.query.customer_id)this.openCreateFromQuery()},methods:{createInstallmentPlan(item){this.$router.push({name:'installment-plans',query:{booking_id:item.id}})},recordPayment(item){this.$router.push({name:'payments',query:{customer_id:item.customer_id,booking_id:item.id}})},createCommission(item){this.$router.push({name:'commissions',query:{booking_id:item.id}})},async openDocuments(item){this.selectedBooking=item;this.documentsDialog=true;this.documentForm={document_type:null,document:null,notes:''};await this.loadDocuments()},async loadDocuments(){if(!this.selectedBooking)return;this.documentsLoading=true;try{const r=await api.get('/bookings/'+this.selectedBooking.id+'/documents');this.documents=r.data||[]}catch(e){this.$root.$emit('show-error','Unable to load booking documents.')}finally{this.documentsLoading=false}},async uploadDocument(){if(!this.selectedBooking||!this.documentForm.document)return;this.uploading=true;try{const fd=new FormData();fd.append('document',this.documentForm.document);fd.append('document_type',this.documentForm.document_type);if(this.documentForm.notes)fd.append('notes',this.documentForm.notes);await api.post('/bookings/'+this.selectedBooking.id+'/documents',fd);this.documentForm={document_type:null,document:null,notes:''};await this.loadDocuments()}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to upload document.')}finally{this.uploading=false}},async downloadDocument(item){try{const r=await api.get('/booking-documents/'+item.id+'/download',{responseType:'blob'});const url=window.URL.createObjectURL(new Blob([r.data]));const a=document.createElement('a');a.href=url;a.download=item.name||'booking-document';document.body.appendChild(a);a.click();a.remove();window.URL.revokeObjectURL(url)}catch(e){this.$root.$emit('show-error','Unable to download document.')}},async deleteDocument(item){if(!window.confirm('Delete this document?'))return;try{await api.delete('/booking-documents/'+item.id);await this.loadDocuments()}catch(e){this.$root.$emit('show-error','Unable to delete document.')}},fileSize(bytes){const n=Number(bytes||0);if(!n)return'-';if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB'},async openCreate(){this.form={customer_id:null,property_id:null,sales_agent_id:null,discount:0,notes:''};this.dialog=true;await this.loadLookups()},async openCreateFromQuery(){await this.openCreate();this.form.customer_id=Number(this.$route.query.customer_id||0)||null;this.form.sales_agent_id=Number(this.$route.query.sales_agent_id||0)||null;const projectId=Number(this.$route.query.project_id||0);const propertyId=Number(this.$route.query.property_id||0);if(projectId)this.properties=this.properties.filter(x=>x.project&&Number(x.project.id)===projectId);if(propertyId&&this.properties.some(x=>Number(x.id)===propertyId))this.form.property_id=propertyId},async loadLookups(){this.loadingCustomers=true;this.loadingProperties=true;this.loadingAgents=true;try{const [c,p,u]=await Promise.all([api.get('/customers',{params:{per_page:100}}),api.get('/properties',{params:{status:'available',per_page:100}}),api.get('/sales-agents')]);this.customers=c.data.data||[];this.properties=(p.data.data||[]).filter(x=>x.status==='available');this.agents=u.data.data||[]}catch(e){this.$root.$emit('show-error','Unable to load booking selections.')}finally{this.loadingCustomers=false;this.loadingProperties=false;this.loadingAgents=false}},async load(){this.loading=true;try{const r=await api.get('/bookings',{params:{search:this.search,status:this.status,per_page:100}});this.items=r.data.data||[]}catch(e){this.$root.$emit('show-error','Unable to load bookings.')}finally{this.loading=false}},money(v){return new Intl.NumberFormat('en-PK',{maximumFractionDigits:0}).format(Number(v||0))},color(s){return{reserved:'orange',confirmed:'blue',completed:'success',cancelled:'grey'}[s]||'grey'},async save(){this.saving=true;try{await api.post('/bookings',this.form);this.dialog=false;await this.load()}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to create booking.')}finally{this.saving=false}},async transition(item,action){const labels={confirm:'confirm this booking',cancel:'cancel this booking',complete:'complete this sale'};if(!window.confirm('Are you sure you want to '+labels[action]+'?'))return;try{await api.post('/bookings/'+item.id+'/'+action);await this.load()}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to update booking.')}}}}
</script>
<style scoped>.page{width:100%}.hero{border-left:4px solid #165134}.summary-card,.filter-card,.table-card{border:1px solid rgba(22,81,52,.08);border-radius:15px!important}.page ::v-deep .v-data-table__wrapper{overflow-x:auto}</style>